#!/usr/bin/env python3
"""Generate crates/html/src/entities.rs from data/html/entities.json.

Run from the repo root: python3 tools/gen_html_entities.py

Source (license in data/html/LICENSE.txt):
  https://html.spec.whatwg.org/entities.json

To update: download the new file over the old one, then run this script.
"""
import json

with open("data/html/entities.json", encoding="utf-8") as f:
    entities = json.load(f)


def rust_str(text):
    """A Rust string literal. Only ASCII, so the generated file is easy to read in any editor."""
    out = []
    for ch in text:
        if ch == '"' or ch == "\\":
            out.append("\\" + ch)
        elif 0x20 <= ord(ch) < 0x7F:
            out.append(ch)
        else:
            out.append("\\u{%X}" % ord(ch))
    return '"' + "".join(out) + '"'


# Keys look like "&amp;" or "&amp". We drop the "&". We sort by name so that Rust can binary search.
rows = sorted((key[1:], value["characters"]) for key, value in entities.items())

with open("crates/html/src/entities.rs", "w", encoding="utf-8") as out:
    out.write("// Generated by tools/gen_html_entities.py from data/html/entities.json. Do not edit.\n")
    out.write("// Source: https://html.spec.whatwg.org/entities.json (CC BY 4.0, see data/html/LICENSE.txt).\n\n")
    out.write("/// Every named character reference: (name without \"&\", text). Sorted by name.\n")
    out.write("/// A name ends with \";\" except for the old names that also work without it, like \"amp\".\n")
    out.write("pub static ENTITIES: &[(&str, &str)] = &[\n")
    for name, chars in rows:
        out.write("    (%s, %s),\n" % (rust_str(name), rust_str(chars)))
    out.write("];\n")
print("wrote", len(rows), "entities")
